#ifdef TAPA_FLOW

#include <cstdint>
#include <tapa.h>
#include "preparation.h"
#include "recurrence_relations.h"
#include "gaussian_qaudrature_opt.h"
#include "compress_store_split.h"

#define TAPA_ARGS_CART_ERIS( z ) tapa::mmap <packed_eri_t> cart_eris_##z,


void t_preparation(
        tapa::mmap<const qp_t> abcd_inp,
        tapa::mmap<const D_WIDTH( qcf::util::next_pow2(sizeof(rys_t) * 8 ))> rtwt_rys_inp,
        n_t n,
        tapa::ostream <D_WIDTH( xyz_derived_pt::bit_width )>& xyz_derived_stream_out,
        tapa::ostream <D_WIDTH( rys_wt_pt::bit_width )>& rys_wt_stream_out,
        tapa::ostream <D_WIDTH( tb_b_pt::bit_width )>& tb_b_stream_out,
        tapa::ostream <D_WIDTH( tb_c_pt::bit_width )>& tb_c_stream_out,
        tapa::ostream <n_t>& n_stream_out
)
{
#pragma hls aggregate variable=abcd_inp
#pragma hls aggregate variable=rtwt_rys_inp
    constexpr int target_ii = std::max( ncg_d * ncg_c, ord_rys * nxyz );

    n_stream_out.write( n );

    for( int i = 0; i < n; ++i )
#pragma hls pipeline II=target_ii
    {
        xyz_derived_pt xyz_derived; /* x, y, z derived for AB, CD, PA, QC, PQ */
        tb_b_pt tb_b;               /* auxiliary B array */
        tb_c_pt tb_c;               /* auxiliary C array */

        rys_t rtwt_rys = *reinterpret_cast<const rys_t*>(&rtwt_rys_inp[i]);
        preparation( abcd_inp[i], rtwt_rys, xyz_derived, tb_b, tb_c );

        rys_wt_pt rys_wt;
        rys_wt.copy_from( rtwt_rys.wt );

        xyz_derived_stream_out.write( xyz_derived );
        rys_wt_stream_out.write( rys_wt );
        tb_b_stream_out.write( tb_b );
        tb_c_stream_out.write( tb_c );
    }
}

void t_recurrence_relations(
        tapa::istream <D_WIDTH( xyz_derived_pt::bit_width )>& xyz_derived_stream_in,
        tapa::istream <D_WIDTH( rys_wt_pt::bit_width )>& rys_wt_stream_in,
        tapa::istream <D_WIDTH( tb_b_pt::bit_width )>& tb_b_stream_in,
        tapa::istream <D_WIDTH( tb_c_pt::bit_width )>& tb_c_stream_in,
        tapa::ostream <D_WIDTH( cba_pt::bit_width )>& dcbaox_stream_out,
        tapa::istream <n_t>& n_stream_in,
        tapa::ostream <n_t>& n_stream_out
)
{
    n_t n = n_stream_in.read();
    n_stream_out.write( n );

    recurrence_relations<am_b, am_d, am_n, am_m, len_a, len_b, len_c, len_d, len_n, len_m, ord_rys>( xyz_derived_stream_in, rys_wt_stream_in, tb_b_stream_in, tb_c_stream_in, dcbaox_stream_out, n );
}

void t_permutation(
        tapa::istream<D_WIDTH( cba_pt::bit_width ) >& dcbaox_stream_in,
        tapa::ostream<D_WIDTH( ba_pt::bit_width ) >& ba_x_stream_out,
        tapa::ostream<D_WIDTH( ba_pt::bit_width ) >& ba_y_stream_out,
        tapa::ostream<D_WIDTH( ba_pt::bit_width ) >& ba_z_stream_out,
        tapa::istream<n_t>& n_stream_in,
        tapa::ostream<n_t>& n_stream_out
)
{
    constexpr int cba_fifo_depth = len_d * ord_rys;
// last fifo doesn't need to hold data as it is consumed right away in dataflow
    hls::stream<cba_pt> cba_x_fifo;
    hls::stream<cba_pt> cba_y_fifo;
    hls::stream<cba_pt> cba_z_fifo;
#pragma hls stream variable=cba_x_fifo type=fifo depth=cba_fifo_depth
#pragma hls stream variable=cba_y_fifo type=fifo depth=cba_fifo_depth
#pragma hls stream variable=cba_z_fifo type=fifo depth=cba_fifo_depth

    n_t n = n_stream_in.read();
    n_stream_out.write( n );

    for( int i_n = 0; i_n < n; ++i_n )
#pragma hls dataflow
    {
        load_xyz_streams<ord_rys, len_d>( dcbaox_stream_in, cba_x_fifo, cba_y_fifo, cba_z_fifo );
        flush_xyz_streams<ord_rys, len_d, len_c>( cba_x_fifo, cba_y_fifo, cba_z_fifo, ba_x_stream_out, ba_y_stream_out, ba_z_stream_out );
    }
}

void t_gaussian_quadrature_a(
        tapa::istream<D_WIDTH( ba_pt::bit_width ) >& ba_x_stream_in,
        tapa::istream<D_WIDTH( ba_pt::bit_width ) >& ba_y_stream_in,
        tapa::istream<D_WIDTH( ba_pt::bit_width ) >& ba_z_stream_in,
        tapa::ostream<D_WIDTH( ba_pt::bit_width ) >& ba_x_stream_out,
        tapa::ostream<D_WIDTH( ba_pt::bit_width ) >& ba_y_stream_out,

#include "internal_types.h"
#include <hls_stream.h>
#include "buffer_permutation.h"
#include "split_merge_stream.h"

using namespace qcf;

extern "C" {
void k_buffer_permutation(
        hls::stream<D_WIDTH( ucba_pt::bit_width / 2 ) >& ucba_stream_in_0,
        hls::stream<D_WIDTH( ucba_pt::bit_width / 2 ) >& ucba_stream_in_1,
        REPEAT( ARGS_UBA_OUT, BP_FIFO_COUNT )
        hls::stream<n_t>& n_stream_in,
        hls::stream<n_t>& n_stream_out
)
{
#pragma hls interface ap_ctrl_none port=return

    constexpr int cba_fifo_depth = qcf::util::ceil_div( bp_phi, bp_fifo_count ) * len_d;
// last fifo doesn't need to hold data as it is consumed right away in dataflow
    hls::stream<D_WIDTH( ucba_pt::bit_width ) > merged_stream;
#if AM_ABCD == 3230 || AM_ABCD == 3231
#define DEF_PKT_FIFOS( z ) hls::stream<ucba_pt> pkt_fifos_##z; \
                           PRAGMA( hls stream variable=pkt_fifos_##z type=fifo depth=cba_fifo_depth )
#else
#define DEF_PKT_FIFOS( z ) hls::stream<ucba_pt> pkt_fifos_##z; \
                           PRAGMA( hls stream variable=pkt_fifos_##z type=fifo depth=cba_fifo_depth ) \
                           PRAGMA( hls bind_storage variable=pkt_fifos_##z type=fifo impl=bram )
#endif
#define PASS_PKT_FIFOS( z ) pkt_fifos_##z,
    REPEAT( DEF_PKT_FIFOS, BP_FIFO_COUNT )

    n_t n = n_stream_in.read();
    n_stream_out.write( n );

    for( int i_n = 0; i_n < n; ++i_n )
    AGGRESSIVE_UNROLL_COND_DATAFLOW_PIPELINE
    {
        merge_stream<bp_phi * len_d, ucba_pt::bit_width>( ucba_stream_in_0, ucba_stream_in_1, merged_stream );
        load_fifos<bp_d, bp_phi, bp_fifo_count>( REPEAT( PASS_PKT_FIFOS, BP_FIFO_COUNT ) merged_stream );
        flush_fifos<bp_d, bp_phi, len_c, bp_fifo_count>( REPEAT( PASS_UBA_OUT, BP_FIFO_COUNT ) REPEAT( PASS_PKT_FIFOS, BP_FIFO_COUNT ) 0 );
    }
}
}

#include "internal_types.h"
#include "compress_store_split.h"
#include "hls_stream.h"
#include "packed_array.hpp"

using namespace qcf;

extern "C" {
void k_compress_store(
        hls::stream<D_WIDTH( ba_cart_eris_pt::bit_width / 2 ) >& cart_eris_stream_in_0,
        hls::stream<D_WIDTH( ba_cart_eris_pt::bit_width / 2 ) >& cart_eris_stream_in_1,
        hls::stream<fp_t>& b_max_stream_in,
        REPEAT( ARGS_CART_ERIS, NUM_ERIS_PORTS )
        int n
)
{
#define INTERFACE_CART_ERIS( z ) PRAGMA( hls interface mode=m_axi port=cart_eris_##z bundle=ce##z max_widen_bitwidth=256 max_write_burst_length=128 )
    REPEAT( INTERFACE_CART_ERIS, NUM_ERIS_PORTS )

    fp_t cart_eris_buf[num_eris_ports * pack_count];
#pragma hls array_partition variable=cart_eris_buf complete dim=0

#ifndef NO_FRP_CS
    fp_t e1, epsilon;
#endif
    N_LOOP:
    for( int i_n = 0; i_n < n; ++i_n )
    AGGRESSIVE_UNROLL_COND_PIPELINE
    {
#ifdef NO_FRP_CS
        fp_t e1, epsilon;
#endif
        STREAM_TO_ERI_PORTS:
        for( int i = 0; i < ncg_d * ncg_c; i++ )
#pragma hls loop_flatten
#ifdef NO_FRP_CS
#pragma hls pipeline II=1
#else
#pragma hls pipeline II=1 style=frp
#endif
        {
            if( i == 0 )
                e1 = calc_epsilon_inv( b_max_stream_in.read(), &epsilon );

            // type conversion needs to be split into 2 lines due to sw_emu bug
            auto uint = (D_WIDTH( ba_cart_eris_pt::bit_width )) (cart_eris_stream_in_1.read(), cart_eris_stream_in_0.read());
	    ba_cart_eris_pt packet = uint;
            for( int j = 0; j < ncg_b * ncg_a; ++j )
                cart_eris_buf[j] = packet[0][j];

#if NUM_ERIS_PORTS > 1
#define ASSIGN_CART_ERIS( z ) cart_eris_##z[i_n * ncg_d * ncg_c + i] = pack_and_compress_eri<pack_count>( &cart_eris_buf[z * pack_count], e1 );
#define REPEAT_ASSIGN_CART_ERIS( n ) REPEAT(ASSIGN_CART_ERIS, n )
            FOR_LAST( REPEAT_ASSIGN_CART_ERIS, NUM_ERIS_PORTS )
#endif

            // duplicate
            constexpr int past_last_eri_index = (ncg_b * ncg_a) - ((num_eris_ports - 1) * pack_count);
#define LAST_PACK_CART_ERIS( z ) packed_eri_t last_pack = pack_and_compress_eri<past_last_eri_index>( &cart_eris_buf[z * pack_count], e1 );
            FOR_LAST( LAST_PACK_CART_ERIS, NUM_ERIS_PORTS )
#pragma hls aggregate variable=last_pack
            memcpy( &last_pack.data[past_last_eri_index], &epsilon, sizeof( fp_t ) );
#define LAST_ASSIGN_CART_ERIS( z ) cart_eris_##z[i_n * ncg_d * ncg_c + i] = last_pack;
            FOR_LAST( LAST_ASSIGN_CART_ERIS, NUM_ERIS_PORTS )
        }
    }
}
}

#include "internal_types.h"
#include "hls_stream.h"
#include "find_bmax.h"

using namespace qcf;
using qcf::util::partial_array_t;
using qcf::util::gq_seg_index_t;

extern "C" {
void k_find_bmax(
#if GQ_KERNEL_SPLIT == 2
        hls::stream<D_WIDTH( ba_cart_eris_a_pt::bit_width / 2 ) >& partial_eris_a_stream_in_0,
        hls::stream<D_WIDTH( ba_cart_eris_a_pt::bit_width / 2 ) >& partial_eris_a_stream_in_1,
#endif
        hls::stream<D_WIDTH( ba_cart_eris_b_pt::bit_width / 2 ) >& partial_eris_b_stream_in_0,
        hls::stream<D_WIDTH( ba_cart_eris_b_pt::bit_width / 2 ) >& partial_eris_b_stream_in_1,
        hls::stream<D_WIDTH( ba_cart_eris_pt::bit_width / 2 ) >& cart_eris_stream_out_0,
        hls::stream<D_WIDTH( ba_cart_eris_pt::bit_width / 2 ) >& cart_eris_stream_out_1,
        hls::stream<fp_t>& b_max_stream_out,
        hls::stream<n_t>& n_stream_in
)
{
#pragma hls interface ap_ctrl_none port=return
    n_t n = n_stream_in.read();

#if AM_ABCD == 3333

    hls::stream<D_WIDTH( ba_cart_eris_pt::bit_width / 2 ) > partial_eris_stream_in_0;
    hls::stream<D_WIDTH( ba_cart_eris_pt::bit_width / 2 ) > partial_eris_stream_in_1;
    N_LOOP:
    for( int i_n = 0; i_n < n; ++i_n )
    AGGRESSIVE_UNROLL_COND_DATAFLOW_PIPELINE
    {
        for( int i = 0; i < ncg_d * ncg_c; i++ )
#pragma hls pipeline II=1
        {
            D_WIDTH( ba_cart_eris_pt::bit_width ) full = ((partial_eris_b_stream_in_1.read(), partial_eris_b_stream_in_0.read()), (partial_eris_a_stream_in_1.read(), partial_eris_a_stream_in_0.read()));
            partial_eris_stream_in_0.write( full.range( ba_cart_eris_pt::bit_width / 2 - 1, 0 ) );
            partial_eris_stream_in_1.write( full.range( ba_cart_eris_pt::bit_width - 1, ba_cart_eris_pt::bit_width / 2 ) );
        }

        find_b_max_passthrough<ncg_d, ncg_c>( partial_eris_stream_in_0, partial_eris_stream_in_1, cart_eris_stream_out_0, cart_eris_stream_out_1, b_max_stream_out);
    }
#else

#if GQ_KERNEL_SPLIT == 2
    find_b_max_passthrough<ncg_d, ncg_c>( partial_eris_a_stream_in_0, partial_eris_a_stream_in_1, partial_eris_b_stream_in_0, partial_eris_b_stream_in_1, cart_eris_stream_out_0, cart_eris_stream_out_1, b_max_stream_out, n );
#elif GQ_KERNEL_SPLIT == 1
    find_b_max_passthrough<ncg_d, ncg_c>( partial_eris_b_stream_in_0, partial_eris_b_stream_in_1, cart_eris_stream_out_0, cart_eris_stream_out_1, b_max_stream_out, n );
#endif
#endif
}
}

#include "internal_types.h"
#include "common/qc_util_advanced.h"
#include <hls_stream.h>
#include "gaussian_qaudrature_opt.h"
#include "split_merge_stream.h"

using namespace qcf;
using qcf::util::partial_array_t;
using qcf::util::gq_seg_index_t;


#if AM_ABCD == 3333 || AM_ABCD == 3332 // could technically be enabled for all rr_unroll_factor == 1 and bp_fifo_count = 3
template<> // specialization for AM_ABCD = 3333 to optimize and allow placement without PCN
void load_dcbaox_bufs_pt<3, bp_phi, ord_rys, len_d, len_c>(
        REPEAT( ARGS_UBA_IN, BP_FIFO_COUNT )
        REPEAT( ARGS_UBA_OUT, BP_FIFO_COUNT )
        ba_pt int_cba_buf_x[ord_rys][len_d * len_c],
        ba_pt int_cba_buf_y[ord_rys][len_d * len_c],
        ba_pt int_cba_buf_z[ord_rys][len_d * len_c]
)
{
    AGGRESSIVE_UNROLL_COND_INLINE
    constexpr int bp_n = bp_fifo_count;

    for( int phi_n = 0; phi_n < qcf::util::ceil_div( bp_phi, bp_n ); ++phi_n ) // bp_phi is total packets, bp_phi_n is max packets per fifo, rr_unroll_factor is num ubas per packet
    {
        for( int d = 0; d < len_d; ++d )
        {
            for( int c = 0; c < len_c; ++c )
#pragma hls loop_flatten
                    COND_REWIND_PIPELINE_II( 1 )
            {
                int o = phi_n; // simplification for rr_unroll_factor = 1, and fifo_count = 3

//               because rr_unroll_factor = 1, ba_pt and uba_pt have same width
                ap_uint<ba_pt::bit_width> uba_x = uba_stream_in_0.read();
                ap_uint<ba_pt::bit_width> uba_y = uba_stream_in_1.read();
                ap_uint<ba_pt::bit_width> uba_z = uba_stream_in_2.read();

                uba_stream_out_0.write( uba_x );
                uba_stream_out_1.write( uba_y );
                uba_stream_out_2.write( uba_z );

                int_cba_buf_x[o][d * len_c + c] = (ba_pt) uba_x;
                int_cba_buf_y[o][d * len_c + c] = (ba_pt) uba_y;
                int_cba_buf_z[o][d * len_c + c] = (ba_pt) uba_z;

            }
        }
    }
}
#endif


extern "C" {
void k_gaussian_quadrature_a(
#if BP_BYPASS == 0
        REPEAT( ARGS_UBA_IN, BP_FIFO_COUNT )
        REPEAT( ARGS_UBA_OUT, BP_FIFO_COUNT )
#elif BP_BYPASS == 1
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_in_0,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_in_1,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_in_2,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_in_3,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_out_0,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_out_1,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_out_2,
        qcf::ostream<D_WIDTH( ucba_pt::bit_width / 4 ) >& ucba_stream_out_3,
#endif
        hls::stream<ap_uint<ba_cart_eris_a_pt::bit_width / 2>>& partial_eris_stream_out_0,
        hls::stream<ap_uint<ba_cart_eris_a_pt::bit_width / 2>>& partial_eris_stream_out_1,
        hls::stream<n_t>& n_stream_in,
        hls::stream<n_t>& n_stream_out
)
{
#pragma hls interface ap_ctrl_none port=return

    constexpr int rys_unroll = ord_rys;

    n_t n = n_stream_in.read();
    n_stream_out.write( n );

    for( int i_n = 0; i_n < n; ++i_n )
    AGGRESSIVE_UNROLL_COND_DATAFLOW_PIPELINE
    {
        ba_pt int_cba_buf_x[rys_unroll][len_d * len_c];
        ba_pt int_cba_buf_y[rys_unroll][len_d * len_c];
        ba_pt int_cba_buf_z[rys_unroll][len_d * len_c];
#if BP_BYPASS == 0
#pragma hls array_partition variable=int_cba_buf_x complete dim=1
#pragma hls array_partition variable=int_cba_buf_y complete dim=1
#pragma hls array_partition variable=int_cba_buf_z complete dim=1
#pragma hls bind_storage variable=int_cba_buf_x type=ram_2p impl=bram
#pragma hls bind_storage variable=int_cba_buf_y type=ram_2p impl=bram
#pragma hls bind_storage variable=int_cba_buf_z type=ram_2p impl=bram
#elif BP_BYPASS == 1
#pragma hls array_partition variable=int_cba_buf_x complete dim=0
#pragma hls array_partition variable=int_cba_buf_y complete dim=0
#pragma hls array_partition variable=int_cba_buf_z complete dim=0
#endif
#pragma hls aggregate variable=int_cba_buf_x
#pragma hls aggregate variable=int_cba_buf_y
#pragma hls aggregate variable=int_cba_buf_z
#if AGGRESSIVE_UNROLL == 0
#pragma hls stream variable=int_cba_buf_x type=pipo depth=2
#pragma hls stream variable=int_cba_buf_y type=pipo depth=2
#pragma hls stream variable=int_cba_buf_z type=pipo depth=2
#endif

#if BP_BYPASS == 0
        load_dcbaox_bufs_pt<bp_fifo_count, bp_phi, rys_unroll, len_d, len_c>( REPEAT( PASS_UBA_IN, BP_FIFO_COUNT ) REPEAT( PASS_UBA_OUT, BP_FIFO_COUNT ) int_cba_buf_x, int_cba_buf_y, int_cba_buf_z );
#elif BP_BYPASS == 1
        static_assert( len_d == 1, "if BP_BYPASS is enabled, len_d must be 1" );
        static_assert( rr_unroll_factor % 3 == 0, "if BP_BYPASS is enabled, rr_unroll_factor must be a multiple of 3" );
        static_assert( ord_rys * nxyz % rr_unroll_factor == 0, "if BP_BYPASS is enabled, ord_rys * nxyz must be a multiple of rr_unroll_factor" );
        for( int i = 0; i < qcf::util::ceil_div( ord_rys * nxyz, rr_unroll_factor ); ++i )
COND_REWIND_PIPELINE_II(1)
        {
            const ap_uint<ucba_pt::bit_width / 4>& ucba_0 = ucba_stream_in_0.read();
            const ap_uint<ucba_pt::bit_width / 4>& ucba_1 = ucba_stream_in_1.read();
            const ap_uint<ucba_pt::bit_width / 4>& ucba_2 = ucba_stream_in_2.read();
            const ap_uint<ucba_pt::bit_width / 4>& ucba_3 = ucba_stream_in_3.read();
            ucba_stream_out_0.write( ucba_0 );
            ucba_stream_out_1.write( ucba_1 );
            ucba_stream_out_2.write( ucba_2 );
            ucba_stream_out_3.write( ucba_3 );
            ucba_pt ucba = (D_WIDTH( ucba_pt::bit_width )) ((D_WIDTH( ucba_pt::bit_width / 2 )) (ucba_3, ucba_2), (D_WIDTH( ucba_pt::bit_width / 2 )) (ucba_1, ucba_0));

            for( int u = 0; u < rr_unroll_factor / 3; ++u )
                for( int c = 0; c < len_c; ++c )
                    for( int b = 0; b < len_b; ++b )
                        for( int a = 0; a < len_a; ++a )
                        {
//                            printf("x[%d][%d][%d][%d]: %f\n", i * (rr_unroll_factor / 3) + u, c, b, a, (fp_t) ucba[u * 3 + 0][c][b][a]);
//                            printf("y[%d][%d][%d][%d]: %f\n", i * (rr_unroll_factor / 3) + u, c, b, a, (fp_t) ucba[u * 3 + 1][c][b][a]);
//                            printf("z[%d][%d][%d][%d]: %f\n", i * (rr_unroll_factor / 3) + u, c, b, a, (fp_t) ucba[u * 3 + 2][c][b][a]);
                            int_cba_buf_x[i * (rr_unroll_factor / 3) + u][c][b][a] = ucba[u * 3 + 0][c][b][a];
                            int_cba_buf_y[i * (rr_unroll_factor / 3) + u][c][b][a] = ucba[u * 3 + 1][c][b][a];
                            int_cba_buf_z[i * (rr_unroll_factor / 3) + u][c][b][a] = ucba[u * 3 + 2][c][b][a];
                        }
        }
#endif
        gaussian_quadrature_split<rys_unroll, len_d, len_c, ncg_d, ncg_c, ncg_b, ncg_a, 0, ncg_b_gq_a>( int_cba_buf_x, int_cba_buf_y, int_cba_buf_z, partial_eris_stream_out_0, partial_eris_stream_out_1 );
    }
}
}

#include "internal_types.h"
#include "common/qc_util_advanced.h"
#include <hls_stream.h>
#include "gaussian_qaudrature_opt.h"
#include "split_merge_stream.h"

using namespace qcf;
using qcf::util::partial_array_t;
using qcf::util::gq_seg_index_t;


#if AM_ABCD == 3333 || AM_ABCD == 3332 // could technically be enabled for all rr_unroll_factor == 1 and bp_fifo_count = 3
template<> // specialization for AM_ABCD = 3333 to optimize and allow placement without PCN
void load_dcbaox_bufs<3, bp_phi, ord_rys, len_d, len_c>(
        REPEAT( ARGS_UBA_IN, BP_FIFO_COUNT )
        ba_pt int_cba_buf_x[ord_rys][len_d * len_c],
        ba_pt int_cba_buf_y[ord_rys][len_d * len_c],
        ba_pt int_cba_buf_z[ord_rys][len_d * len_c]
)
{
    AGGRESSIVE_UNROLL_COND_INLINE
    constexpr int bp_n = bp_fifo_count;

    for( int phi_n = 0; phi_n < qcf::util::ceil_div( bp_phi, bp_n ); ++phi_n ) // bp_phi is total packets, bp_phi_n is max packets per fifo, rr_unroll_factor is num ubas per packet
    {
