    return static_cast<unsigned long long>(lhs) != rhs.operator unsigned long long();
}

template<int _AP_W>
inline bool operator<=(int lhs, const ap_uint<_AP_W>& rhs) {
    return static_cast<unsigned long long>(lhs) <= rhs.operator unsigned long long();
}

template<int _AP_W>
